import { expect, test, uniqueName } from "../../fixtures";

const MiB = 1024 * 1024;

const examples = [
  {
    label: "an empty file",
    file: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) },
    kind: "w9",
    status: 422,
    code: "empty_file",
  },
  {
    label: "a file of exactly 10 MiB + 1",
    file: {
      name: "too-large.pdf",
      mimeType: "application/pdf",
      buffer: Buffer.alloc(10 * MiB + 1, 0x25),
    },
    kind: "w9",
    status: 413,
    code: "file_too_large",
  },
  {
    label: 'a ".exe" file',
    file: {
      name: "payload.exe",
      mimeType: "application/x-msdownload",
      buffer: Buffer.from("MZ\x90\x00 not really an executable"),
    },
    kind: "w9",
    status: 415,
    code: "unsupported_type",
  },
  {
    label: "a valid text file",
    file: { name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("hello vendor") },
    kind: "passport",
    status: 422,
    code: "validation_error",
  },
] as const;

test.describe("@DOC-04 Upload vendor documents", () => {
  for (const example of examples) {
    test(
      `rejects ${example.label} as kind "${example.kind}" with ${example.status} ${example.code}`,
      { tag: "@DOC-04" },
      async ({ apiAs }) => {
        // Arrange: a draft vendor owned by the signed-in member, with a unique name.
        const member = await apiAs("member");
        const vendorResponse = await member.post("/api/vendors", {
          data: {
            name: uniqueName("DOC-04 Vendor"),
            category: "services",
            contact_email: `doc04-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@northwind.test`,
          },
        });
        expect(vendorResponse.status()).toBe(201);
        const vendor = await vendorResponse.json();
        expect(vendor.status).toBe("draft");

        // Act: upload the invalid document.
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: example.kind,
            file: example.file,
          },
        });

        // Assert: status and error code from the scenario.
        expect(response.status()).toBe(example.status);
        const body = await response.json();
        expect(body.error.code).toBe(example.code);
      },
    );
  }
});
